def registry(r):
    return airframe_plan.Registry(r["dev"], tuple(r["upper"]), r["tenants"], r["owner"])


def tools(r):
    return AirframeTools(MemoryKube([]), FakeValidator(), registry(r), cluster="hangar-dev")


def spec(**kw):
    s = {"apiVersion": "airframe/v1", "kind": "AppSpec", "app": "parachute", "stack": "python",
         "environments": {"ground": ["dev"], "flight": [{"name": "prod"}]}}
    s.update(kw)
    return s


def with_(base, path, value):
    """A copy of base with value set at a /-separated path (a leading ! removes the key)."""
    b = copy.deepcopy(base)
    cur = b
    parts = path.split("/")
    for p in parts[:-1]:
        cur = cur[int(p)] if isinstance(cur, list) else cur.setdefault(p, {})
    last = parts[-1]
    if value == "!":
        cur.pop(last)
    elif isinstance(cur, list):
        cur[int(last)] = value
    else:
        cur[last] = value
    return b


