def result(fn):
    try:
        return {"expect": json.loads(json.dumps(fn(), default=str))}
    except Exception as e:  # the exception a Python caller would see
        return {"raises": type(e).__name__}


def cap_cases():
    t = tools(REG)
    cs = []

    def add(name, **kw):
        a = {k: v for k, v in kw.items() if v is not None}
        cs.append({"name": name, "tool": "capabilities", "args": a, **result(lambda: t.capabilities(kw.get("kind"), kw.get("section")))})

    add("default")
    for sec in ("appspec", "chart", "xrds", "components", "targets", "kinds", "$schema", "generated_by", "nope", "Chart"):
        add(f"section {sec}", section=sec)
    every = {**CONTRACT["components"], **CONTRACT.get("targets", {}), **CONTRACT.get("kinds", {})}
    for n, (key, sc) in enumerate(every.items()):
        add(f"kind {sc['kind']}", kind=sc["kind"])
        if n % 6 == 0:   # the lookup by key and by plural, for a few
            add(f"kind by key {key}", kind=key.upper())
            add(f"kind by plural {sc['kind']}", kind=(CONTRACT["xrds"].get(sc["kind"]) or {}).get("plural") or key.upper())
    add("kind unknown", kind="queue")
    add("kind wins over section", kind="MessageQueue", section="chart")
    add("kind lower case", kind="messagequeue")
    return cs


def explain_cases():
    t = tools(REG)
    cs = []

    def add(name, rule):
        cs.append({"name": name, "tool": "explain", "args": {"rule": rule}, **result(lambda: t.explain(rule))})

    for r in AF_RULES:
        add(f"rule {r}", r)
    every = {**CONTRACT["components"], **CONTRACT.get("targets", {}), **CONTRACT.get("kinds", {})}
    ids = []
    for sc in every.values():
        for k in sc.get("knownFailures") or []:
            ids.append(k["id"])
        for c in sc.get("conditions") or []:
            for r in c.get("reasons") or []:
                ids.append(r["reason"])
    for i in sorted(set(ids)):
        add(f"id {i}", i)
    for g in GENERIC_FAILURES:
        add(f"generic {g['id']}", g["id"])
    add("unknown", "AF-NOPE-001")
    add("empty", "")
    add("lower case rule", "af-schema-001")
    add("number", 7)
    add("null", None)
    add("a quote in it", "it's")
    add("a list", ["AF-SCHEMA-001"])
    add("a mapping", {"a": 1})
    return cs


def sorted_keys(v):
    """v with every mapping's keys in sorted order (lists keep theirs): what the Go gateway sees of an agent's arguments."""
    if isinstance(v, dict):
        return {k: sorted_keys(v[k]) for k in sorted(v)}
    if isinstance(v, list):
        return [sorted_keys(x) for x in v]
    return v


WHY_ORDER = ("the MCP arguments reach the Go handler as a map, which has no key order, so every mapping is read with its keys "
             "sorted; a message that quotes an offending object, or text built from one, shows it in that order (Python keeps the "
             "agent's)")


def corpus():
    out = []
    for c in plan_cases():
        t = tools(c["registry"])
        res = result(lambda: t.plan(copy.deepcopy(c["spec"]), copy.deepcopy(c["baseCicd"])))
        case = {**c, **res}
        # What Go answers for the same arguments once their key order is gone.
        base = c["baseCicd"]
        res2 = result(lambda: t.plan(sorted_keys(copy.deepcopy(c["spec"])), sorted_keys(copy.deepcopy(base)) if isinstance(base, dict) else base))
        if res2 != res:
            case["go"], case["why"] = res2["expect"], WHY_ORDER
        out.append(case)
    return out + cap_cases() + explain_cases()


def outputs() -> dict:
    cases = corpus()
    # one case a line: a diff of the fixture reads, and the file stays small
    return {OUT: '{"cases": [\n' + ",\n".join(json.dumps(c, ensure_ascii=True, separators=(",", ":")) for c in cases) + "\n]}\n"}


if __name__ == "__main__":
    for p, t in outputs().items():
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(t)
        print(p, len(t))
